package com.devtunasoft.tuneros.qa23

import com.devtunasoft.tuneros.core.DashSegmentIndex
import com.devtunasoft.tuneros.core.HlsByteRange
import java.io.File
import java.lang.reflect.Modifier
import java.nio.ByteBuffer
import java.nio.charset.StandardCharsets
import java.nio.file.Files
import java.security.MessageDigest
import java.util.HexFormat
import kotlin.system.exitProcess

/**
 * QA-23 host gate: bounded DASH SegmentBase sidx index admission.
 *
 * Compiled together with the real production DashSegmentIndex and its pure-Kotlin
 * HlsByteRange model. The fixture is generated byte-for-byte from constants, pinned
 * by a manifest, and every case is fed to the production parser. Negative controls
 * mutate fixture rows or one production guard at a time; the runner pins each first
 * failure code. No fixture text, address-like value or derived token is emitted.
 */
object Qa23Gate {
    const val SEED = 20261123L

    private const val LARGE_REFS = 10_000
    private const val LARGE_RANGE_OFFSET = 8_192L
    private val DATA_FILES = listOf("contract.txt", "cases.tsv", "large.idx")
    private val ALL_FILES = listOf("contract.txt", "cases.tsv", "large.idx", "dimensions.tsv", "sha256.txt")
    private val DIMENSION_KEYS = listOf(
        "fixture_version", "index_cases", "large_refs", "large_model_sha256", "manifest_sha256",
    )
    private val CASE_HEADER = "id\thex\trangeOffset\trangeLength\texpect\tdetail"
    private val DIMENSION_HEADER = "field\tvalue"

    private const val ACCEPT = "ACCEPT"
    private const val REJECT = "REJECT"

    private val EXPECTED = linkedMapOf(
        "V0_VALID" to ACCEPT,
        "V1_VALID" to ACCEPT,
        "TRUNCATED" to REJECT,
        "BAD_TYPE" to REJECT,
        "BAD_VERSION" to REJECT,
        "ZERO_TIMESCALE" to REJECT,
        "NO_REFS" to REJECT,
        "HIER_REF" to REJECT,
        "EMPTY_REF" to REJECT,
        "ZERO_DURATION" to REJECT,
        "RANGE_MISMATCH" to REJECT,
        "OVERSIZE" to REJECT,
        "BYTE_OVERFLOW" to REJECT,
    )

    private val CHECK_BY_ID = mapOf(
        "TRUNCATED" to "TRUNCATED_REJECT",
        "BAD_TYPE" to "TYPE_REJECT",
        "BAD_VERSION" to "VERSION_REJECT",
        "ZERO_TIMESCALE" to "TIMESCALE_REJECT",
        "NO_REFS" to "NO_REFS_REJECT",
        "HIER_REF" to "HIER_REJECT",
        "EMPTY_REF" to "EMPTY_REF_REJECT",
        "ZERO_DURATION" to "ZERO_DUR_REJECT",
        "RANGE_MISMATCH" to "RANGE_REJECT",
        "OVERSIZE" to "OVERSIZE_REJECT",
        "BYTE_OVERFLOW" to "OVERFLOW_REJECT",
    )

    private val urlPattern = Regex("(?i)(https?|ftp|file)://")
    private val secretPattern = Regex(
        "(?i)(password|passwd|secret|credential|personal[_-]?code|access[_-]?marker|pin[_-]?code|recording[_-]?payload|aes[_-]?key|drm[_-]?key)\\s*[:=]",
    )
    private val hex = HexFormat.of()
    private val idPattern = Regex("^[A-Z0-9_]+$")

    class GateFailure(val code: String) : Exception(code)

    private fun bad(code: String): Nothing = throw GateFailure(code)

    private fun ByteArray.toHex(): String = hex.formatHex(this)

    private fun fromHex(text: String): ByteArray = try {
        hex.parseHex(text)
    } catch (error: IllegalArgumentException) {
        bad("HEX_STRICT")
    }

    private fun digest(bytes: ByteArray): String = MessageDigest.getInstance("SHA-256").digest(bytes).toHex()

    private fun derivedToken(): String = ByteArray(16) { index ->
        ((SEED ushr (8 * (index % 4))) xor (index * 41L + 7L)).toByte()
    }.toHex()

    private fun derivedMarker(): String = "qa23marker" + Integer.toHexString((SEED xor 0x3C3C3C3CL).toInt())

    private fun be16(value: Int): ByteArray = ByteBuffer.allocate(2).putShort(value.toShort()).array()
    private fun be32(value: Long): ByteArray = ByteBuffer.allocate(4).putInt(value.toInt()).array()
    private fun be64(value: Long): ByteArray = ByteBuffer.allocate(8).putLong(value).array()

    private data class RefSpec(val length: Long, val duration: Long, val hierarchical: Boolean = false)

    private data class BoxSpec(
        val version: Int,
        val timescale: Long,
        val firstOffset: Long,
        val refs: List<RefSpec>,
        val type: String = "sidx",
        val versionField: Int = version,
        val countOverride: Int? = null,
        val sizeField: Int? = null,
    )

    private fun headerBytes(version: Int): Int = if (version == 0) 32 else 40

    private fun buildBox(spec: BoxSpec): ByteArray {
        val header = headerBytes(spec.version)
        val count = spec.countOverride ?: spec.refs.size
        val declared = spec.sizeField?.toLong() ?: (header.toLong() + 12L * count)
        val actual = header + 12 * spec.refs.size
        val out = ByteBuffer.allocate(actual)
        out.put(be32(declared))
        out.put(spec.type.toByteArray(Charsets.US_ASCII))
        out.put(spec.versionField.toByte())
        out.put(byteArrayOf(0, 0, 0))
        out.put(be32(1L))
        out.put(be32(spec.timescale))
        if (spec.version == 0) {
            out.put(be32(0L))
            out.put(be32(spec.firstOffset))
        } else {
            out.put(be64(0L))
            out.put(be64(spec.firstOffset))
        }
        out.put(be16(0))
        out.put(be16(count))
        for (ref in spec.refs) {
            val word = (if (ref.hierarchical) 0x8000_0000L else 0L) or ref.length
            out.put(be32(word))
            out.put(be32(ref.duration))
            out.put(be32(0L))
        }
        return out.array()
    }

    private data class CaseRow(
        val id: String, val box: ByteArray, val rangeOffset: Long, val rangeLength: Long,
        val expect: String, val detail: String,
    )

    private data class LargeModel(val bytes: ByteArray, val refs: Int)

    private class Built(val files: Map<String, ByteArray>, val large: LargeModel)

    private fun modelDigest(timescale: Long, refs: List<Triple<Long, Long, Long>>): String {
        val text = StringBuilder().append(timescale).append('\n')
        for (ref in refs) {
            text.append(ref.first).append('|').append(ref.second).append('|').append(ref.third).append('\n')
        }
        return digest(text.toString().toByteArray(StandardCharsets.UTF_8))
    }

    private fun largeModel(): LargeModel {
        val refs = List(LARGE_REFS) { RefSpec(1_000L, 1_000L) }
        return LargeModel(buildBox(BoxSpec(0, 90_000L, 0L, refs)), LARGE_REFS)
    }

    private fun expectedLargeModelDigest(largeSize: Int): String {
        var offset = LARGE_RANGE_OFFSET + largeSize.toLong()
        val triples = ArrayList<Triple<Long, Long, Long>>(LARGE_REFS)
        repeat(LARGE_REFS) {
            triples += Triple(offset, 1_000L, 1_000L)
            offset += 1_000L
        }
        return modelDigest(90_000L, triples)
    }

    private fun build(): Built {
        val contract = StringBuilder()
            .append("QA-23 scratch fixture for bounded DASH SegmentBase sidx index admission.\n")
            .append("Every address-like value is symbolic; no feed address, access marker, personal code, PIN or media text is stored.\n")
            .append("Index boxes are generated from fixed constants; no private recording payload is present.\n")
            .append("Rows carry ids, digests and outcomes only. Fixture bytes are LF encoded.\n")
            .toString().toByteArray(StandardCharsets.UTF_8)

        val v0 = BoxSpec(0, 90_000L, 1_024L, listOf(RefSpec(4_000L, 3_000L), RefSpec(4_001L, 3_000L), RefSpec(4_002L, 3_000L)))
        val v1 = BoxSpec(1, 48_000L, 2_048L, listOf(RefSpec(2_000L, 1_500L), RefSpec(2_001L, 1_500L)))
        val cases = linkedMapOf<String, CaseRow>()
        fun add(
            id: String, spec: BoxSpec, offset: Long, length: Long? = null,
            expect: String, detail: String,
        ) {
            val box = buildBox(spec)
            cases[id] = CaseRow(id, box, offset, length ?: box.size.toLong(), expect, detail)
        }
        add("V0_VALID", v0, 4_096L, expect = ACCEPT, detail = "90000:3")
        add("V1_VALID", v1, 4_096L, expect = ACCEPT, detail = "48000:2")
        add("TRUNCATED", BoxSpec(0, 90_000L, 0L, listOf(RefSpec(100L, 100L), RefSpec(100L, 100L)),
            countOverride = 3, sizeField = 56),
            4_096L, expect = REJECT, detail = "DASH SegmentBase index is truncated")
        add("BAD_TYPE", BoxSpec(0, 90_000L, 0L, listOf(RefSpec(100L, 100L)), type = "sndx"),
            4_096L, expect = REJECT, detail = "DASH SegmentBase index is not a sidx box")
        add("BAD_VERSION", BoxSpec(0, 90_000L, 0L, listOf(RefSpec(100L, 100L)), versionField = 2),
            4_096L, expect = REJECT, detail = "DASH SegmentBase index version is not supported")
        add("ZERO_TIMESCALE", BoxSpec(0, 0L, 0L, listOf(RefSpec(100L, 100L))),
            4_096L, expect = REJECT, detail = "DASH SegmentBase index timescale is not positive")
        add("NO_REFS", BoxSpec(0, 90_000L, 0L, emptyList()),
            4_096L, expect = REJECT, detail = "DASH SegmentBase index has no references")
        add("HIER_REF", BoxSpec(0, 90_000L, 0L, listOf(RefSpec(100L, 100L, hierarchical = true))),
            4_096L, expect = REJECT, detail = "DASH SegmentBase hierarchical index is not supported")
        add("EMPTY_REF", BoxSpec(0, 90_000L, 0L, listOf(RefSpec(0L, 100L))),
            4_096L, expect = REJECT, detail = "DASH SegmentBase index has an empty subsegment")
        add("ZERO_DURATION", BoxSpec(0, 90_000L, 0L, listOf(RefSpec(100L, 0L))),
            4_096L, expect = REJECT, detail = "DASH SegmentBase index has a zero-duration subsegment")
        val mismatchBox = buildBox(BoxSpec(0, 90_000L, 0L, listOf(RefSpec(100L, 100L))))
        cases["RANGE_MISMATCH"] = CaseRow("RANGE_MISMATCH", mismatchBox, 4_096L, mismatchBox.size.toLong() + 1L,
            REJECT, "DASH SegmentBase index range is not the bytes requested")
        cases["OVERSIZE"] = CaseRow("OVERSIZE", mismatchBox, 4_096L, 200_001L,
            REJECT, "DASH SegmentBase index is too large")
        add("BYTE_OVERFLOW", BoxSpec(1, 90_000L, 1_000_000_000_000_000L, listOf(RefSpec(1_000L, 1L))),
            8_192L, expect = REJECT, detail = "DASH SegmentBase index offsets are too large")

        val caseText = StringBuilder().append(CASE_HEADER).append('\n')
        for (row in cases.values) {
            caseText.append(row.id).append('\t').append(row.box.toHex()).append('\t')
                .append(row.rangeOffset).append('\t').append(row.rangeLength).append('\t')
                .append(row.expect).append('\t').append(row.detail).append('\n')
        }

        val large = largeModel()
        val data = linkedMapOf(
            "contract.txt" to contract,
            "cases.tsv" to caseText.toString().toByteArray(StandardCharsets.UTF_8),
            "large.idx" to large.bytes,
        )
        val manifest = StringBuilder()
        for (name in DATA_FILES) manifest.append(digest(data.getValue(name))).append("  ").append(name).append('\n')
        val manifestBytes = manifest.toString().toByteArray(StandardCharsets.UTF_8)

        val dimensions = StringBuilder().append(DIMENSION_HEADER).append('\n')
        dimensions.append("fixture_version\t1\n")
        dimensions.append("index_cases\t").append(cases.size).append('\n')
        dimensions.append("large_refs\t").append(large.refs).append('\n')
        dimensions.append("large_model_sha256\t").append(expectedLargeModelDigest(large.bytes.size)).append('\n')
        dimensions.append("manifest_sha256\t").append(digest(manifestBytes)).append('\n')

        data["sha256.txt"] = manifestBytes
        data["dimensions.tsv"] = dimensions.toString().toByteArray(StandardCharsets.UTF_8)
        return Built(data, large)
    }

    private fun rows(text: String, header: String, fields: Int, code: String): List<List<String>> {
        val parts = text.split('\n').let { if (it.isNotEmpty() && it.last().isEmpty()) it.dropLast(1) else it }
        if (parts.isEmpty() || parts[0] != header) bad(code)
        return parts.drop(1).map { line ->
            val columns = line.split('\t')
            if (columns.size != fields) bad("FIELD_COUNT")
            columns
        }
    }

    private fun parseCases(bytes: ByteArray): List<CaseRow> =
        rows(String(bytes, StandardCharsets.UTF_8), CASE_HEADER, 6, "CASE_HEADER_STRICT").map { c ->
            if (!idPattern.matches(c[0])) bad("ENUM_STRICT")
            if (c[2].toLongOrNull() == null || c[3].toLongOrNull() == null) bad("INT_BOUNDS")
            if (c[4] != ACCEPT && c[4] != REJECT) bad("ENUM_STRICT")
            if (c[5].isEmpty()) bad("FIELD_COUNT")
            CaseRow(c[0], fromHex(c[1]), c[2].toLong(), c[3].toLong(), c[4], c[5])
        }

    private fun parseDimensions(bytes: ByteArray): Map<String, String> {
        val result = LinkedHashMap<String, String>()
        for (c in rows(String(bytes, StandardCharsets.UTF_8), DIMENSION_HEADER, 2, "DIMENSION_HEADER_STRICT")) {
            if (c[0] !in DIMENSION_KEYS) bad("ENUM_STRICT")
            if (result.put(c[0], c[1]) != null) bad("FIELD_COUNT")
        }
        if (result.size != DIMENSION_KEYS.size) bad("FIELD_COUNT")
        return result
    }

    private fun parseManifest(bytes: ByteArray): Map<String, String> {
        val result = LinkedHashMap<String, String>()
        val lineRegex = Regex("^([0-9a-f]{64})  ([a-z0-9.\\-]+)$")
        for (line in String(bytes, StandardCharsets.UTF_8).split('\n').let {
            if (it.isNotEmpty() && it.last().isEmpty()) it.dropLast(1) else it
        }) {
            val match = lineRegex.matchEntire(line) ?: bad("MANIFEST_FORMAT")
            if (result.put(match.groupValues[2], match.groupValues[1]) != null) bad("FIELD_COUNT")
        }
        if (result.keys.toSet() != DATA_FILES.toSet()) bad("FIELD_COUNT")
        return result
    }

    private fun readFixtures(dir: File): Map<String, ByteArray> {
        val files = dir.listFiles()?.filter { it.name != ".gitattributes" }?.associateBy { it.name }
            ?: bad("FIXTURE_DIR_MISSING")
        if (files.keys.toSet() != ALL_FILES.toSet()) bad("FIXTURE_FILE_SET")
        return ALL_FILES.associateWith { name -> files.getValue(name).readBytes() }
    }

    private class Report {
        val lines = mutableListOf<String>()
        var checks = 0
        var pass = 0
        var fail = 0
        var first: String? = null

        fun check(id: String, ok: Boolean) {
            checks++
            if (ok) {
                pass++
                lines.add("CHECK\tPASS\t$id")
            } else {
                fail++
                lines.add("CHECK\tFAIL\t$id")
                if (first == null) first = id
            }
        }

        fun thrown(code: String) {
            fail++
            lines.add("FAIL\t$code")
            if (first == null) first = code
        }

        fun emit(summary: Boolean = true) {
            if (summary) lines.add(
                "SUMMARY\tchecks=$checks\tpass=$pass\tfail=$fail\tfirst=${first ?: "NONE"}",
            )
            for (line in lines) println(line)
        }
    }

    private class Oracle(val timescale: Long, val firstOffset: Long, val refs: List<RefSpec>)

    /** Independent decoder for the ACCEPT cases; never calls production code. */
    private fun oracle(box: ByteArray): Oracle {
        if (box.size < 32) bad("ORACLE_BOUNDS")
        val buffer = ByteBuffer.wrap(box)
        val size = buffer.int
        if (size != box.size) bad("ORACLE_SIZE")
        val version = box[8].toInt() and 0xFF
        var pos = 12
        pos += 4 // reference_ID
        val timescale = buffer.getInt(pos).toLong() and 0xFFFF_FFFFL
        pos += 4
        val firstOffset: Long
        if (version == 0) {
            pos += 4
            firstOffset = buffer.getInt(pos).toLong() and 0xFFFF_FFFFL
            pos += 4
        } else {
            pos += 8
            firstOffset = buffer.getLong(pos)
            pos += 8
        }
        pos += 2
        val count = buffer.getShort(pos).toInt() and 0xFFFF
        pos += 2
        if (pos + 12 * count != box.size) bad("ORACLE_BOUNDS")
        val refs = ArrayList<RefSpec>(count)
        repeat(count) {
            val word = buffer.getInt(pos).toLong() and 0xFFFF_FFFFL
            val duration = buffer.getInt(pos + 4).toLong() and 0xFFFF_FFFFL
            pos += 12
            refs += RefSpec(word and 0x7FFF_FFFFL, duration)
        }
        return Oracle(timescale, firstOffset, refs)
    }

    private fun sidxOutcome(bytes: ByteArray, rangeOffset: Long, rangeLength: Long): DashSegmentIndex.Outcome =
        DashSegmentIndex.parse(bytes, HlsByteRange(length = rangeLength, offset = rangeOffset))

    private fun privacyClean(diagnostics: String, fixtures: Map<String, ByteArray>, injected: String?): Boolean {
        val haystack = StringBuilder(diagnostics)
        if (injected != null) haystack.append('\n').append(injected)
        for (bytes in fixtures.values) haystack.append('\n').append(String(bytes, StandardCharsets.ISO_8859_1))
        val text = haystack.toString()
        return !text.contains(derivedToken()) &&
            !text.contains(derivedMarker()) &&
            !urlPattern.containsMatchIn(text) &&
            !secretPattern.containsMatchIn(text)
    }

    private fun modelDigestOf(outcome: DashSegmentIndex.Outcome.Parsed): String {
        val triples = outcome.references.map { Triple(it.range.offset, it.range.length, it.durationTicks) }
        return modelDigest(outcome.timescale, triples)
    }

    private fun boundedCycles(large: ByteArray, pinnedDigest: String, pinnedRefs: Int, report: Report) {
        val startThreads = Thread.activeCount()
        var baseline = -1L
        var ok = true
        var digestOk = true
        repeat(4) { cycle ->
            val outcome = sidxOutcome(large, LARGE_RANGE_OFFSET, large.size.toLong())
            if (outcome !is DashSegmentIndex.Outcome.Parsed) {
                ok = false
            } else {
                digestOk = digestOk && modelDigestOf(outcome) == pinnedDigest &&
                    outcome.references.size == pinnedRefs
            }
            System.gc()
            Thread.sleep(30)
            val used = Runtime.getRuntime().totalMemory() - Runtime.getRuntime().freeMemory()
            if (cycle == 0) baseline = used else ok = ok && used - baseline <= 8L * 1024 * 1024
            ok = ok && Thread.activeCount() <= startThreads + 2
        }
        val leaked = Thread.getAllStackTraces().keys.any { it.name.startsWith("qa23-") }
        report.check("BOUNDED_CYCLES", ok && digestOk && !leaked)
    }

    private fun noStaticCaches(): Boolean = DashSegmentIndex::class.java.declaredFields.none { field ->
        Modifier.isStatic(field.modifiers) &&
            (Collection::class.java.isAssignableFrom(field.type) ||
                Map::class.java.isAssignableFrom(field.type) ||
                field.type.isArray)
    }

    private fun verify(mode: String, dir: File, report: Report) {
        val committed = readFixtures(dir)
        val built = build()
        val dimensions = parseDimensions(committed.getValue("dimensions.tsv"))
        if (mode == "verify-mutant-raw") {
            val manifest = parseManifest(committed.getValue("sha256.txt"))
            val manifestOk = digest(committed.getValue("sha256.txt")) == dimensions.getValue("manifest_sha256") &&
                DATA_FILES.all { digest(committed.getValue(it)) == manifest[it] }
            report.check("MANIFEST_MISMATCH", manifestOk)
            return
        }
        if (mode == "verify") {
            report.check(
                "BYTE_IDENTITY",
                ALL_FILES.all { built.files.getValue(it).contentEquals(committed.getValue(it)) },
            )
            report.check(
                "MANIFEST_DATA",
                digest(committed.getValue("sha256.txt")) == dimensions.getValue("manifest_sha256") &&
                    parseManifest(committed.getValue("sha256.txt")).let { m ->
                        DATA_FILES.all { digest(committed.getValue(it)) == m[it] }
                    },
            )
        }
        val cases = parseCases(committed.getValue("cases.tsv"))
        report.check(
            "DIMENSIONS",
            dimensions.getValue("fixture_version") == "1" &&
                dimensions.getValue("index_cases").toIntOrNull() == cases.size &&
                cases.size == EXPECTED.size,
        )
        report.check(
            "CASE_COVERAGE",
            cases.map { it.id }.toSet() == EXPECTED.keys &&
                cases.size == EXPECTED.size &&
                cases.distinctBy { it.id }.size == cases.size,
        )
        report.check("EXPECT_CONSISTENCY", cases.all { EXPECTED[it.id] == it.expect })

        for (case in cases) {
            val code = CHECK_BY_ID[case.id] ?: continue
            if (case.expect != REJECT) continue
            val outcome = sidxOutcome(case.box, case.rangeOffset, case.rangeLength)
            val rejected = outcome is DashSegmentIndex.Outcome.Refused && outcome.reason == case.detail
            report.check(code, rejected)
        }

        var vectorOk = true
        for (case in cases) {
            if (case.expect != ACCEPT) continue
            val outcome = sidxOutcome(case.box, case.rangeOffset, case.rangeLength)
            if (outcome !is DashSegmentIndex.Outcome.Parsed) {
                vectorOk = false
                continue
            }
            val expected = oracle(case.box)
            val expectedParts = case.detail.split(':')
            if (expectedParts.size != 2) {
                vectorOk = false
                continue
            }
            val expectedTimescale = expectedParts[0].toLongOrNull()
            val expectedCount = expectedParts[1].toIntOrNull()
            var offset = case.rangeOffset + case.box.size.toLong() + expected.firstOffset
            var refOk = outcome.references.size == expected.refs.size &&
                outcome.timescale == expected.timescale &&
                outcome.timescale == expectedTimescale &&
                outcome.references.size == expectedCount
            for (index in outcome.references.indices) {
                val actual = outcome.references[index]
                val wanted = expected.refs[index]
                refOk = refOk && actual.range.offset == offset &&
                    actual.range.length == wanted.length &&
                    actual.durationTicks == wanted.duration
                offset += wanted.length
            }
            vectorOk = vectorOk && refOk
        }
        report.check("SIDX_VECTOR", vectorOk)

        val large = committed.getValue("large.idx")
        val pinnedRefs = dimensions.getValue("large_refs").toIntOrNull() ?: bad("INT_BOUNDS")
        val capOk = large.size == built.large.bytes.size &&
            pinnedRefs == built.large.refs &&
            pinnedRefs == LARGE_REFS &&
            large.size.toLong() == 32L + 12L * pinnedRefs
        report.check("CAP_BINDING", capOk)
        if (capOk) boundedCycles(large, dimensions.getValue("large_model_sha256"), pinnedRefs, report)
        report.check("NO_STATIC_CACHE", noStaticCaches())

        val injected = if (mode == "verify-leak") derivedToken() else null
        report.check("PRIVACY_SCAN", privacyClean(report.lines.joinToString("\n"), committed, injected))
    }

    private fun generate(dir: File, report: Report) {
        val built = build()
        Files.createDirectories(dir.toPath())
        for (name in ALL_FILES) {
            val bytes = built.files.getValue(name)
            Files.write(dir.resolve(name).toPath(), bytes)
            report.lines.add("GENERATE\t$name\tbytes=${bytes.size}\tsha256=${digest(bytes)}")
        }
    }

    @JvmStatic
    fun main(args: Array<String>) {
        if (args.size < 2) {
            println("FAIL\tUSAGE\tmode plus fixture directory required")
            exitProcess(2)
        }
        val mode = args[0]
        val dir = File(args[1])
        val report = Report()
        try {
            if (mode == "generate") {
                generate(dir, report)
                report.emit(summary = false)
                return
            }
            if (mode !in setOf("verify", "verify-mutant", "verify-mutant-raw", "verify-leak")) bad("MODE_STRICT")
            verify(mode, dir, report)
        } catch (failure: GateFailure) {
            report.thrown(failure.code)
        } catch (error: Throwable) {
            report.thrown("GATE_EXCEPTION:${error.javaClass.simpleName}")
        }
        report.emit()
        exitProcess(if (report.first == null) 0 else 1)
    }
}
